"""Binary data format conversion utilities"""

from __future__ import annotations

import typing
from typing import Union, Optional, Any

from ctc import spec


def get_binary_format(data: spec.BinaryData) -> spec.BinaryFormat:
    """Get the format of binary data"""
    if isinstance(data, str):
        if data.startswith('0x'):
            return 'prefix_hex'
        else:
            return 'raw_hex'
    elif isinstance(data, bytes):
        return 'binary'
    elif isinstance(data, int):
        return 'integer'
    else:
        raise ValueError(f"Unknown data type: {type(data)}")


def get_binary_n_bytes(data: spec.BinaryData) -> int:
    """Get the number of bytes in binary data"""
    if isinstance(data, str):
        if data.startswith('0x'):
            return len(data[2:]) // 2
        else:
            return len(data) // 2
    elif isinstance(data, bytes):
        return len(data)
    elif isinstance(data, int):
        return (data.bit_length() + 7) // 8
    else:
        raise ValueError(f"Unknown data type: {type(data)}")


def match_format(format_this: spec.BinaryData, like_this: spec.BinaryData) -> spec.BinaryData:
    """Match the format of format_this to like_this"""
    target_format = get_binary_format(like_this)
    return convert(format_this, target_format)


def convert(
    data: spec.BinaryData,
    output_format: spec.BinaryFormat,
    *,
    library: Optional[typing.Literal['pysha3', 'pycryptodome', 'hashlib']] = None,
) -> spec.BinaryInteger:
    """Convert binary data to specified format"""

    # Handle different input types
    if isinstance(data, str):
        if data.startswith('0x'):
            # Hex string
            try:
                binary_data = bytes.fromhex(data[2:])
            except ValueError:
                # If it's not valid hex, treat as text
                binary_data = data.encode('utf-8')
        else:
            # Text string
            binary_data = data.encode('utf-8')
    elif isinstance(data, int):
        # Integer - convert to bytes
        byte_length = (data.bit_length() + 7) // 8
        if byte_length == 0:
            byte_length = 1
        binary_data = data.to_bytes(byte_length, 'big')
    elif isinstance(data, bytes):
        binary_data = data
    else:
        # Try to convert to bytes
        binary_data = bytes(data)

    # Convert to desired output format
    if output_format == 'binary':
        return binary_data
    elif output_format == 'raw_hex':
        return binary_data.hex()
    elif output_format == 'prefix_hex':
        return '0x' + binary_data.hex()
    elif output_format == 'integer':
        return int.from_bytes(binary_data, 'big')
    else:
        raise ValueError(f"Unknown output format: {output_format}")


def is_hex_string(data: str) -> bool:
    """Check if string is a valid hex string"""
    if not isinstance(data, str):
        return False
    if data.startswith('0x'):
        data = data[2:]
    try:
        int(data, 16)
        return True
    except ValueError:
        return False


def is_prefix_hex_string(data: str) -> bool:
    """Check if string is a valid prefix hex string"""
    if not isinstance(data, str):
        return False
    return data.startswith('0x') and is_hex_string(data)


def remove_prefix_hex(data: str) -> str:
    """Remove '0x' prefix from hex string"""
    if data.startswith('0x'):
        return data[2:]
    return data


def add_prefix_hex(data: str) -> str:
    """Add '0x' prefix to hex string"""
    if data.startswith('0x'):
        return data
    return '0x' + data


def hex_to_bytes(data: str) -> bytes:
    """Convert hex string to bytes"""
    return bytes.fromhex(remove_prefix_hex(data))


def bytes_to_hex(data: bytes, prefix: bool = True) -> str:
    """Convert bytes to hex string"""
    hex_str = data.hex()
    if prefix:
        return '0x' + hex_str
    return hex_str


def to_bytes(data: spec.BinaryData) -> bytes:
    """Convert any binary data to bytes"""
    return convert(data, 'binary')


def to_hex(data: spec.BinaryData, prefix: bool = True) -> str:
    """Convert any binary data to hex string"""
    hex_str = convert(data, 'raw_hex')
    if prefix:
        return '0x' + hex_str
    return hex_str


def to_integer(data: spec.BinaryData) -> int:
    """Convert any binary data to integer"""
    return convert(data, 'integer')
